export const heartReference={url:'https://sketchfab.com/3d-models/internal-human-heart-anatomy-9f48eaa481cc4a43baeb9e1f03882cff',embed:'https://sketchfab.com/models/9f48eaa481cc4a43baeb9e1f03882cff/embed',author:'Alexandra Wilkins · University of Dundee, CAHID'};
export function openHeartReference(dialog){
 if(!dialog.open)dialog.showModal();
 dialog.innerHTML='<button class="dialog-close" aria-label="Kalp referansını kapat">×</button><span class="eyebrow">AYRINTILI 3B REFERANS · ÇEVRİMİÇİ</span><h2>Kalbin iç yapısı</h2><p>Kordalar, kapaklar, papiller kaslar, trabeküller ve odacıkları aynı modelde incele.</p><div class="heart-reference-frame"></div><p class="heart-reference-credit"></p><div class="heart-reference-guide"><h3>İnceleme sırası</h3><ol><li>Sağ ve sol karıncığı, aralarındaki septumla ayırt et.</li><li>Atriyoventriküler kapaklardan papiller kaslara uzanan kordaları takip et.</li><li>Papiller kasları, iç duvardaki trabeküler çıkıntılarla karşılaştır.</li><li>Aort ve pulmoner kapaklarda korda bağlantısı bulunmadığını incele.</li></ol></div><p>Bu bağımsız üniversite modeli internet gerektirir. Yerel atlasın arama, katman ve kesit kontrolleri bu görüntüye uygulanmaz.</p>';
 const frame=document.createElement('iframe');frame.title='University of Dundee · Internal Human Heart Anatomy';frame.src=heartReference.embed;frame.allow='fullscreen; xr-spatial-tracking';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';dialog.querySelector('.heart-reference-frame').append(frame);
 const credit=dialog.querySelector('.heart-reference-credit');credit.append(document.createTextNode(heartReference.author+' · '));const link=document.createElement('a');link.href=heartReference.url;link.target='_blank';link.rel='noreferrer';link.textContent='Kaynak model / görüntü açılmazsa burada incele ↗';credit.append(link);
 dialog.querySelector('.dialog-close').onclick=()=>dialog.close();
 dialog.addEventListener('close',()=>{frame.src='about:blank';frame.remove();},{once:true});
}
